package com.minimarket.proveedor.controller; import org.springframework.security.access.prepost.PreAuthorize;
import com.minimarket.common.ApiResponse; import com.minimarket.proveedor.dto.*; import com.minimarket.proveedor.service.ProveedorService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @PreAuthorize("hasAuthority('PROVEEDOR_ADMINISTRAR')") @RequestMapping("/api/proveedores") @RequiredArgsConstructor public class ProveedorController{private final ProveedorService s;@GetMapping public ApiResponse<Page<ProveedorResponseDTO>> listar(Pageable p){return ApiResponse.ok(s.listar(p));}@GetMapping("/{id}")public ApiResponse<ProveedorResponseDTO> one(@PathVariable Long id){return ApiResponse.ok(s.obtener(id));}@GetMapping("/documento/{tipo}/{numero}")public ApiResponse<ProveedorResponseDTO> doc(@PathVariable String tipo,@PathVariable String numero){return ApiResponse.ok(s.porDocumento(tipo,numero));}@PostMapping@ResponseStatus(HttpStatus.CREATED)public ApiResponse<ProveedorResponseDTO> crear(@Valid@RequestBody ProveedorRequestDTO r){return ApiResponse.ok(s.crear(r));}@PutMapping("/{id}")public ApiResponse<ProveedorResponseDTO> upd(@PathVariable Long id,@Valid@RequestBody ProveedorRequestDTO r){return ApiResponse.ok(s.actualizar(id,r));}@DeleteMapping("/{id}")public ApiResponse<Void> del(@PathVariable Long id){s.desactivar(id);return ApiResponse.ok(null,"Proveedor desactivado");}}